import Foundation

// Reads one `message_N.html` of a Meta "Download your information" export (Facebook Messenger or Instagram).
// Structure only: a page is a header (`<title>`, FB also "Generated by <name> on
// <date> ... UTC+hh:mm") followed by one block per message, newest first:
//
//   block   div.._a6-g   (IG: "pam _3-95 _2ph- _a6-g uiBoxWhite noborder")
//     label   div._a6-h [+ _a6-i when it names a sender]   sender display name; without _a6-i it is the FB "Participants: ..." line
//     content div._a6-p > one wrapper div > direct children by position:
//               [1] message text (<br /> = newline), [2] link-preview box (anchors), [3] unused,
//               [4+] media (a/img, video, audio, file anchors), a reactions <ul._a6-q>, a call-duration span._idm, "IP address: ..."
//     time    div._a6-o   "Jan 05, 2019 3:22:15 pm" (FB) / "Jan 05, 2019 3:22 pm" (IG)

public struct MetaMediaRef: Hashable, Sendable {
    public enum Kind: Sendable { case image, video, audio, file }
    public var path: String          // export-root relative (the page's <base> is the export root)
    public var kind: Kind
}

public struct MetaBlock: Sendable {
    public var sender: String?           // label naming a sender
    public var labelOnly: String?        // a label with no sender (the participants line)
    public var text = ""
    public var shareLinks: [String] = []
    public var media: [MetaMediaRef] = []
    public var reactions: [(emoji: String, name: String)] = []
    public var callDetail: String?
    public var emojiImages: [String] = [] // remote inline images in the text (emoji drawn as pictures; the export carries no codepoint)
    public var timeText = ""
}

public struct MetaFile: Sendable {
    public var title = ""
    public var header = ""               // FB: "Generated by <name> on <date> at <time> UTC+hh:mm"
    public var blocks: [MetaBlock] = []
}

public enum MetaFileParser {
    public static func parse(data: Data) -> MetaFile {
        let handler = Handler()
        data.withUnsafeBytes { raw in
            let buf = raw.bindMemory(to: UInt8.self)
            HTMLScanner.scan(buf, delegate: handler)
        }
        handler.finish()
        return handler.file
    }

    public static func parse(prefix data: Data, bytes: Int) -> MetaFile {
        parse(data: data.prefix(bytes))
    }

    static let emojiMark = "\u{E000}"

    static func isRemote(_ s: String) -> Bool {
        let l = s.lowercased()
        return l.hasPrefix("http") || l.hasPrefix("//")
    }

    /// Splits a reaction string "<emoji><name>" at the end of the leading run of emoji characters (by Unicode emoji
    /// properties, so a display name that starts with a plain symbol is left alone).
    static func splitEmoji(_ s: String) -> (emoji: String, rest: String) {
        func isEmoji(_ c: Character) -> Bool {
            let sc = c.unicodeScalars
            if sc.contains(where: { $0.value == 0xFE0F || $0.properties.isEmojiPresentation || (0x1F3FB...0x1F3FF).contains($0.value) }) { return true }
            if let f = sc.first, f.properties.isEmoji, f.value >= 0x203C { return true }
            return false
        }
        var emoji = ""
        var rest = Substring(s)
        while let c = rest.first, isEmoji(c) { emoji.append(c); rest = rest.dropFirst() }
        return (emoji, rest.trimmingCharacters(in: .whitespacesAndNewlines))
    }

    // MARK: class tokens

    struct Flags: OptionSet {
        let rawValue: UInt16
        static let block = Flags(rawValue: 1), label = Flags(rawValue: 2), labelUser = Flags(rawValue: 4)
        static let content = Flags(rawValue: 8), time = Flags(rawValue: 16), reactions = Flags(rawValue: 32)
        static let idm = Flags(rawValue: 64), header = Flags(rawValue: 128)
    }

    static func flags(of cls: UnsafeBufferPointer<UInt8>?) -> Flags {
        guard let cls else { return [] }
        var f: Flags = []
        var i = 0
        let n = cls.count
        while i < n {
            while i < n && cls[i] == 0x20 { i += 1 }
            let s = i
            while i < n && cls[i] != 0x20 { i += 1 }
            let t = UnsafeBufferPointer(rebasing: cls[s..<i])
            if t.count == 5, t[0] == 0x5F, t[1] == 0x61 { // _a....
                if t[2] == 0x36, t[3] == 0x2D { // _a6-?
                    switch t[4] {
                    case 0x67: f.insert(.block)      // g
                    case 0x68: f.insert(.label)      // h
                    case 0x69: f.insert(.labelUser)  // i
                    case 0x70: f.insert(.content)    // p
                    case 0x6F: f.insert(.time)       // o
                    case 0x71: f.insert(.reactions)  // q
                    default: break
                    }
                } else if t[2] == 0x6F, t[3] == 0x61, t[4] == 0x61 { f.insert(.header) }   // _aoaa
            } else if t.count == 4, t[0] == 0x5F, t[1] == 0x69, t[2] == 0x64, t[3] == 0x6D { f.insert(.idm) }   // _idm
        }
        return f
    }

    // MARK: handler

    private final class Handler: HTMLScannerDelegate {
        struct Frame { var tag: HTMLTag; var flags: Flags; var idx: Int32 }

        var file = MetaFile()
        var stack: [Frame] = []
        var counters: [Int32] = [0]        // counters[d] = element children seen so far under stack depth d

        var blockDepth = -1, labelDepth = -1, contentDepth = -1, timeDepth = -1, liDepth = -1, idmDepth = -1, headerDepth = -1
        var inTitle = false
        var cur = MetaBlock()
        var hasSender = false
        var labelBuf = "", textBuf = "", timeBuf = "", callBuf = ""
        var pieces: [String] = []
        var emojiURLs: [String] = []

        // The element directly under the content wrapper that we are inside (its position among the wrapper's children).
        func itemIndex() -> Int32? {
            guard contentDepth >= 0, stack.count > contentDepth + 2 else { return nil }
            return stack[contentDepth + 2].idx
        }

        func startTag(_ tag: HTMLTag, attrs: HTMLAttrs, selfClosing: Bool) {
            if tag == .style || tag == .script { push(tag, [], record: false); return }
            if tag == .title { inTitle = true }
            let fl = MetaFileParser.flags(of: attrs.cls)

            if blockDepth >= 0 && contentDepth >= 0 {
                switch tag {
                case .br:
                    if itemIndex() == 1 && liDepth < 0 { textBuf.append("\n") }
                case .img:
                    if let src = attrs.src {
                        let s = HTMLEntities.decode(src)
                        if MetaFileParser.isRemote(s) {
                            if itemIndex() == 1 { emojiURLs.append(s); textBuf.append(MetaFileParser.emojiMark) }
                        } else if !s.lowercased().hasPrefix("data:") { addMedia(s, .image) }
                    }
                case .video: if let src = attrs.src { addMedia(HTMLEntities.decode(src), .video) }
                case .audio: if let src = attrs.src { addMedia(HTMLEntities.decode(src), .audio) }
                case .a:
                    if let href = attrs.href, liDepth < 0 {
                        let h = HTMLEntities.decode(href)
                        let idx = itemIndex() ?? 0
                        if idx == 2 { if MetaFileParser.isRemote(h), !cur.shareLinks.contains(h) { cur.shareLinks.append(h) } }
                        else if idx >= 3, !MetaFileParser.isRemote(h), !h.lowercased().hasPrefix("data:") { addMedia(h, .file) }
                    }
                case .li:
                    if liDepth < 0 { pieces = [] }
                default: break
                }
            }
            if selfClosing { counters[stack.count] += 1; return }
            push(tag, fl, record: true)
        }

        func addMedia(_ path: String, _ kind: MetaMediaRef.Kind) {
            var p = path
            if p.contains("%"), let d = p.removingPercentEncoding { p = d }
            if let ex = cur.media.firstIndex(where: { $0.path == p }) {
                // the anchor around an image repeats its path as a file link; keep the more specific kind
                if cur.media[ex].kind == .file && kind != .file { cur.media[ex].kind = kind }
                return
            }
            cur.media.append(MetaMediaRef(path: p, kind: kind))
        }

        func push(_ tag: HTMLTag, _ fl: Flags, record: Bool) {
            let d = stack.count
            let idx = counters[d]
            counters[d] += 1
            stack.append(Frame(tag: tag, flags: fl, idx: idx))
            counters.append(0)
            guard record else { return }
            let depth = stack.count - 1       // index of the frame just pushed
            if fl.contains(.block) && blockDepth < 0 {
                blockDepth = depth
                cur = MetaBlock(); hasSender = false
                labelBuf = ""; textBuf = ""; timeBuf = ""; callBuf = ""; pieces = []
                emojiURLs = []
            } else if blockDepth >= 0 {
                if fl.contains(.label) && labelDepth < 0 { labelDepth = depth; hasSender = fl.contains(.labelUser) }
                else if fl.contains(.content) && contentDepth < 0 { contentDepth = depth }
                else if fl.contains(.time) && timeDepth < 0 { timeDepth = depth }
                else if fl.contains(.idm) && idmDepth < 0 && contentDepth >= 0 { idmDepth = depth }
                if tag == .li && contentDepth >= 0 && liDepth < 0 && depth > contentDepth { liDepth = depth }
            }
            if fl.contains(.header) && headerDepth < 0 { headerDepth = depth }
        }

        /// Closes whatever a truncated or malformed page left open, so a block cut short is still delivered.
        func finish() { while !stack.isEmpty { pop() } }

        func endTag(_ tag: HTMLTag) {
            if tag == .title { inTitle = false }
            guard let k = stack.lastIndex(where: { $0.tag == tag }) else { return }
            while stack.count > k { pop() }
        }

        func pop() {
            let depth = stack.count - 1
            stack.removeLast()
            counters.removeLast()
            if depth == liDepth { finishReaction(); liDepth = -1 }
            if depth == labelDepth { labelDepth = -1 }
            if depth == contentDepth { contentDepth = -1 }
            if depth == timeDepth { timeDepth = -1 }
            if depth == idmDepth { idmDepth = -1 }
            if depth == headerDepth { headerDepth = -1 }
            if depth == blockDepth {
                blockDepth = -1
                finishBlock()
            }
        }

        func finishReaction() {
            // A piece in parentheses is the time the reaction was made ("(Mon DD, YYYY h:mm am)"): not part of emoji or name.
            let ps = pieces.map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                .filter { !$0.isEmpty && !($0.hasPrefix("(") && $0.hasSuffix(")")) }
            pieces = []
            guard !ps.isEmpty else { return }
            let (emoji, rest) = MetaFileParser.splitEmoji(ps[0])
            let name = ([rest] + ps.dropFirst()).filter { !$0.isEmpty }.joined(separator: " ")
            cur.reactions.append((emoji.isEmpty ? "?" : emoji, name))
        }

        func finishBlock() {
            let label = labelBuf.trimmingCharacters(in: .whitespacesAndNewlines)
            if hasSender { cur.sender = label.isEmpty ? nil : label }
            else if !label.isEmpty { cur.labelOnly = label }
            cur.text = textBuf.trimmingCharacters(in: .whitespacesAndNewlines)
            cur.timeText = timeBuf.trimmingCharacters(in: .whitespacesAndNewlines)
            let call = callBuf.trimmingCharacters(in: .whitespacesAndNewlines)
            if !call.isEmpty { cur.callDetail = call }
            cur.emojiImages = emojiURLs
            if !emojiURLs.isEmpty {
                let mark = MetaFileParser.emojiMark
                if cur.text.replacingOccurrences(of: mark, with: "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { cur.text = "" }
                else { cur.text = cur.text.replacingOccurrences(of: mark, with: "[emoji]") }
            }
            file.blocks.append(cur)
        }

        func text(_ bytes: UnsafeBufferPointer<UInt8>) {
            if inTitle && blockDepth < 0 { file.title += HTMLEntities.decode(bytes); return }
            if headerDepth >= 0 && blockDepth < 0 { file.header += HTMLEntities.decode(bytes); return }
            guard blockDepth >= 0 else { return }
            if labelDepth >= 0 { labelBuf += HTMLEntities.decode(bytes); return }
            if timeDepth >= 0 { timeBuf += HTMLEntities.decode(bytes); return }
            guard contentDepth >= 0 else { return }
            if liDepth >= 0 { pieces.append(HTMLEntities.decode(bytes)); return }
            if idmDepth >= 0 { callBuf += HTMLEntities.decode(bytes); return }
            if itemIndex() == 1 { textBuf += HTMLEntities.decode(bytes) }
        }
    }
}

// MARK: timestamps

/// Meta renders every message time as wall-clock text in one fixed offset and never says which in the message itself.
/// Facebook states it in the page header ("... UTC+08:00"); Instagram states nothing (its fixed
/// -08:00 was established by comparing real exports against other copies of the same messages).
public enum MetaTime {
    public enum Zone: Sendable, Equatable {
        case fixed(seconds: Int)
        case named(String)           // fallback with DST
    }

    public struct Civil: Equatable, Sendable { public var y, mo, d, h, mi, s: Int }

    static let months: [String: Int] = ["jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
                                        "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12]

    /// "Jan 05, 2019 3:22:15 pm" or "Jan 05, 2019 3:22 pm" (also U+202F / U+00A0 before am/pm, upper-case AM/PM).
    public static func parse(_ raw: String) -> Civil? {
        var tokens: [Substring] = []
        let s = raw.replacingOccurrences(of: "\u{202F}", with: " ").replacingOccurrences(of: "\u{00A0}", with: " ")
        var start = s.startIndex
        var inTok = false
        for i in s.indices {
            let c = s[i]
            let sep = c == " " || c == "," || c == ":"
            if sep { if inTok { tokens.append(s[start..<i]); inTok = false } }
            else if !inTok { start = i; inTok = true }
        }
        if inTok { tokens.append(s[start...]) }
        // Mon DD YYYY H MM [SS] am|pm
        guard tokens.count == 6 || tokens.count == 7,
              let mo = months[tokens[0].lowercased().prefix(3).description],
              let d = Int(tokens[1]), let y = Int(tokens[2]), let h12 = Int(tokens[3]), let mi = Int(tokens[4]) else { return nil }
        let sec = tokens.count == 7 ? Int(tokens[5]) : 0
        guard let sec else { return nil }
        let ap = tokens[tokens.count - 1].lowercased()
        guard ap == "am" || ap == "pm", (1...12).contains(h12), (1...31).contains(d), (0...59).contains(mi), (0...60).contains(sec) else { return nil }
        let h = h12 % 12 + (ap == "pm" ? 12 : 0)
        return Civil(y: y, mo: mo, d: d, h: h, mi: mi, s: sec)
    }

    /// Days since 1970-01-01 of a proleptic Gregorian date.
    static func daysFromCivil(_ y0: Int, _ m: Int, _ d: Int) -> Int {
        let y = m <= 2 ? y0 - 1 : y0
        let era = (y >= 0 ? y : y - 399) / 400
        let yoe = y - era * 400
        let doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1
        let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
        return era * 146097 + doe - 719468
    }

    public static func unixMs(_ c: Civil, zone: Zone) -> Int64? {
        switch zone {
        case .fixed(let off):
            let days = daysFromCivil(c.y, c.mo, c.d)
            return (Int64(days) * 86400 + Int64(c.h * 3600 + c.mi * 60 + c.s) - Int64(off)) * 1000
        case .named(let id):
            guard let tz = TimeZone(identifier: id) else { return nil }
            var cal = Calendar(identifier: .gregorian)
            cal.timeZone = tz
            var dc = DateComponents()
            dc.year = c.y; dc.month = c.mo; dc.day = c.d; dc.hour = c.h; dc.minute = c.mi; dc.second = c.s
            guard let date = cal.date(from: dc) else { return nil }
            return Int64((date.timeIntervalSince1970 * 1000).rounded())
        }
    }

    /// "UTC+08:00" / "UTC-05:00" anywhere in a header line.
    public static func offset(inHeader h: String) -> Int? {
        guard let r = h.range(of: "UTC") else { return nil }
        let rest = h[r.upperBound...]
        guard let sign = rest.first, sign == "+" || sign == "-" else { return nil }
        let digits = rest.dropFirst().prefix(5)
        let parts = digits.split(separator: ":")
        guard parts.count == 2, let hh = Int(parts[0]), let mm = Int(parts[1]) else { return nil }
        return (sign == "-" ? -1 : 1) * (hh * 3600 + mm * 60)
    }

    /// "Generated by <name> on <weekday>, <month> <d>, <yyyy> at ..." -> name.
    public static func generatedBy(inHeader h: String) -> String? {
        guard let a = h.range(of: "Generated by "), let b = h.range(of: " on ", range: a.upperBound..<h.endIndex) else { return nil }
        let name = String(h[a.upperBound..<b.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines)
        return name.isEmpty ? nil : name
    }
}
